def transform(g):
    import copy
    g=[row[:] for row in g]; H,W=len(g),len(g[0])
    # origins of shapes: top-left of bounding boxes of connected 2-components
    seen=[[False]*W for _ in range(H)]; origs=[]
    def comp(r0,c0):
        st=[(r0,c0)]; cells=[]
        seen[r0][c0]=True
        while st:
            r,c=st.pop(); cells.append((r,c))
            for dr,dc in((1,0),(-1,0),(0,1),(0,-1)):
                nr,nc=r+dr,c+dc
                if 0<=nr<H and 0<=nc<W and g[nr][nc]==2 and not seen[nr][nc]:
                    seen[nr][nc]=True; st.append((nr,nc))
        return cells
    for r in range(H):
        for c in range(W):
            if g[r][c]==2 and not seen[r][c]:
                cells=comp(r,c)
                mr=min(x[0] for x in cells); mc=min(x[1] for x in cells)
                origs.append((mr,mc))
    origs=sorted(set(origs))
    # shape cell pattern from first origin
    r0,c0=origs[0]
    # find shape extent: scan the component grid properly - rebuild pattern by checking cells within bbox
    # recompute: pattern cells = offsets of 2-cells of the first component
    seen=[[False]*W for _ in range(H)]
    def comp2(r0,c0):
        st=[(r0,c0)]; cells=[]; seen[r0][c0]=True
        while st:
            r,c=st.pop(); cells.append((r-r0,c-c0))
            for dr,dc in((1,0),(-1,0),(0,1),(0,-1)):
                nr,nc=r+dr,c+dc
                if 0<=nr<H and 0<=nc<W and g[nr][nc]==2 and not seen[nr][nc]:
                    seen[nr][nc]=True; st.append((nr,nc))
        return cells
    pattern=set(comp2(r0,c0))
    # spacing d: min gap between distinct origin rows/cols >0
    rows=sorted({o[0] for o in origs}); cols=sorted({o[1] for o in origs})
    d=min([b-a for a,b in zip(rows,rows[1:]) if b-a>1]+[b-a for a,b in zip(cols,cols[1:]) if b-a>1])
    slots={(o[0]//d,o[1]//d) for o in origs}
    missing=sorted(pattern-slots)
    # remove 3s
    for r in range(H):
        for c in range(W):
            if g[r][c]==3: g[r][c]=0
    new_origs=list(origs)
    for (sr,sc) in missing:
        orr,occ=sr*d,sc*d
        for (pr,pc) in pattern:
            g[orr+pr][occ+pc]=2
        new_origs.append((orr,occ))
    for (orr,occ) in new_origs:
        sr,sc=orr//d,occ//d
        g[orr+sr][occ+sc]=8
    return g

